local makeText = (function()
-- A presentation-only catalog: translated labels never replace gameplay identifiers.
return function(catalog, scope)
	local values, templates, cache = {}, {}, {}
	for _, section in ipairs({ "Shared", scope }) do
		for key, value in pairs(type(catalog[section]) == "table" and catalog[section] or {}) do
			if type(key) == "string" and type(value) == "string" then values[key] = value end
		end
	end
	local specifier = "%%[-+ #0%d%.]*[cdeEfgGiouXxsq]"
	local function escape(value) return (value:gsub("([%(%)%.%%%+%-%*%?%[%]%^%$])", "%%%1")) end
	for source, replacement in pairs(values) do
		if source ~= replacement and source:find(specifier) then
			local pattern, cursor, count = "^", 1, 0
			while true do
				local first, last = source:find(specifier, cursor)
				if not first then break end
				pattern ..= escape(source:sub(cursor, first - 1)) .. "(.-)"
				cursor, count = last + 1, count + 1
			end
			table.insert(templates, { Pattern = pattern .. escape(source:sub(cursor)) .. "$", Replacement = replacement, Length = #source })
		elseif source ~= replacement and source:match("%s$") then
			table.insert(templates, { Pattern = "^" .. escape(source) .. "(.*)$", Replacement = replacement .. "%s", Length = #source })
		elseif source ~= replacement and source:match("^%s") then
			table.insert(templates, { Pattern = "^(.*)" .. escape(source) .. "$", Replacement = "%s" .. replacement, Length = #source })
		end
	end
	table.sort(templates, function(a, b) return a.Length > b.Length end)
	local cacheCount = 0
	return function(value)
		if type(value) ~= "string" then return value end
		if values[value] ~= nil then return values[value] end
		if cache[value] then return cache[value] end
		for _, template in ipairs(templates) do
			local captures = table.pack(value:match(template.Pattern))
			if captures[1] ~= nil then
				local index = 0
				local result = template.Replacement:gsub(specifier, function()
					index += 1
					local captured = captures[index] or ""
					return values[captured] or captured
				end)
				cacheCount += 1
				if cacheCount > 256 then table.clear(cache); cacheCount = 1 end
				cache[value] = result
				return result
			end
		end
		return value
	end
end

end)()

-- Loader
do
-- Each API instance owns its configuration and module cache.
local settings = { BaseUrl = "https://raw.githubusercontent.com/Fwrostt/FrostScripts/main" }
local cache, loading = {}, {}
local freshRequestCount = 0
local games = {}
for _, entry in ipairs(API.Catalog) do
	assert(type(entry.Id) == "string" and not games[entry.Id], "Catalog IDs must be unique strings")
	assert(type(entry.Name) == "string" and type(entry.Description) == "string", "Catalog entries need a name and description")
	assert(type(entry.EntryPoint) == "string" and entry.EntryPoint:match("^games/[%w_/-]+%.lua$"), "EntryPoint must be a Lua file under games/")
	games[entry.Id] = entry
end
local function copy(value)
	if type(value) ~= "table" then return value end
	local result = {}
	for key, item in pairs(value) do result[key] = copy(item) end
	return result
end

function API.Configure(options)
	options = options or {}
	local base = options.BaseUrl or settings.BaseUrl
	assert(options.Mode == nil or options.Mode == "http", "FrostScripts loads only from GitHub over HTTPS")
	assert(type(base) == "string", "BaseUrl must be a string")
	base = base:gsub("/+$", "")
	assert(base:match("^https://raw%.githubusercontent%.com/Fwrostt/FrostScripts/[%w%._/%-]+$"),
		"Use a raw.githubusercontent.com/Fwrostt/FrostScripts branch or commit URL")
	assert(next(loading) == nil, "Cannot change configuration while a module is loading")
	settings = { BaseUrl = base }
	table.clear(cache)
	return API
end

function API.GetConfig()
	return table.clone(settings)
end

function API.LoadModule(path, expectedMethod, fresh, ...)
	assert(type(path) == "string" and path:match("^[%w_/%-%.]+%.lua$")
		and not path:find("..", 1, true) and path:sub(1, 1) ~= "/", "Invalid module path")
	if not fresh and cache[path] ~= nil then
		assert(not expectedMethod or type(cache[path][expectedMethod]) == "function", path .. " has an incompatible interface")
		return cache[path]
	end
	assert(not loading[path], "Circular module load: " .. path)
	assert(type(loadstring) == "function", "FrostScripts requires loadstring")
	loading[path] = true
	local args = table.pack(...)
	local ok, result = pcall(function()
		local url = settings.BaseUrl .. "/" .. path
		if fresh then
			freshRequestCount += 1
			url ..= "?frost=" .. tostring(os.time()) .. "_" .. tostring(math.floor(os.clock() * 1000000)) .. "_" .. tostring(freshRequestCount)
		end
		local source = game:HttpGet(url)
		assert(type(source) == "string" and #source > 0, "Empty source for " .. path)
		local chunk, compileError = loadstring(source, "@FrostScripts/" .. path)
		assert(chunk, compileError)
		local value = chunk(table.unpack(args, 1, args.n))
		assert(type(value) == "table", path .. " must return a table")
		assert(not expectedMethod or type(value[expectedMethod]) == "function", path .. " has an incompatible interface")
		return value
	end)
	loading[path] = nil
	assert(ok, "FrostScripts could not load " .. path .. ": " .. tostring(result))
	if not fresh then cache[path] = result end
	return result
end

function API.LoadUI()
	-- Fresh UI factories isolate window theme state between game suites.
	local library = API.LoadModule("dist/ui/UI.lua", "new", true)
	local createWindow = library.CreateWindow
	if type(createWindow) == "function" then
		library.CreateWindow = function(self, options)
			options = table.clone(options or {})
			options.UIState = API.UIState
			options.ResolveCover = API.ResolveCover
			options.ResolveAsset = API.ResolveAsset
			options.TextData = API.TextData
			if not options.IsLauncher then options.OnReturnToLibrary = API.ReturnToLauncher end
			return createWindow(self, options)
		end
	end
	return library
end

function API.UnloadGame()
	if API.ActiveSuite then
		API.ActiveSuite:Unload()
		API.ActiveSuite, API.ActiveGame = nil, nil
	end
end

function API.RunGame(name)
	local entry = games[name]
	assert(entry, "Unsupported script: " .. tostring(name))
	assert(not API._gameLoading, "Another script is still loading")
	assert(#(entry.PlaceIds or {}) == 0 or table.find(entry.PlaceIds, game.PlaceId), "Open " .. entry.Name .. " in its supported game first")
	API._gameLoading = true
	local ok, suite = pcall(function()
		API.UnloadGame()
		return API.LoadModule(entry.EntryPoint, "Unload", true, API)
	end)
	API._gameLoading = false
	assert(ok, suite)
	API.ActiveSuite, API.ActiveGame = suite, name
	return suite
end

function API.GetGames()
	local names = {}
	for _, entry in ipairs(API.Catalog) do table.insert(names, entry.Id) end
	return names
end

function API.GetCatalog()
	return copy(API.Catalog)
end

function API.OpenLauncher()
	API.ReloadText()
	return API.LoadModule("dist/launcher/App.lua", "Unload", true, API)
end
end

-- Assets
do
-- Optional GitHub image bridge. Executable source never uses the filesystem.
local imageCache = {}
local extensions = { "png", "jpg", "jpeg" }

local function resolveImage(path, cacheKey)
	if type(path) ~= "string" or not path:match("^[%w_/%-%.]+$")
		or path:find("..", 1, true) or path:sub(1, 1) == "/" then
		return nil, "Invalid image path"
	end
	local extension = path:lower():match("%.(png)$") or path:lower():match("%.(jpe?g)$")
	if not extension then return nil, "Only PNG and JPEG images are supported" end
	local register = getcustomasset or getsynasset
	if type(writefile) ~= "function" or type(register) ~= "function" then
		return nil, "GitHub images require writefile and getcustomasset support"
	end
	local url = API.GetConfig().BaseUrl .. "/" .. path
	cacheKey = cacheKey or url
	if imageCache[cacheKey] then return imageCache[cacheKey] end
	local ok, bytes = pcall(function() return game:HttpGet(url) end)
	if not ok or type(bytes) ~= "string" or #bytes > 4 * 1024 * 1024 then return nil, "Image download failed" end
	local png = extension == "png" and #bytes >= 24 and bytes:sub(1, 8) == "\137PNG\r\n\26\n"
	local jpeg = extension ~= "png" and #bytes >= 4 and bytes:sub(1, 3) == "\255\216\255"
	if not png and not jpeg then return nil, "Invalid image data" end
	local hash = 5381
	for index = 1, #bytes do hash = (hash * 33 + bytes:byte(index)) % 4294967296 end
	local filename = "FrostScripts_image_" .. path:gsub("[^%w_-]", "_") .. "_" .. string.format("%08x", hash) .. "." .. extension
	local saved, content = pcall(function()
		writefile(filename, bytes)
		return register(filename)
	end)
	if not saved or type(content) ~= "string" or content == "" then return nil, "Image registration failed" end
	imageCache[cacheKey] = content
	return content
end

function API.ResolveAsset(path)
	return resolveImage(path)
end

function API.ResolveCover(entry)
	if type(entry) ~= "table" or type(entry.EntryPoint) ~= "string" then return nil, "Invalid catalog entry" end
	if type(entry.Image) == "table" and entry.Image.Enabled == false then return nil, "Disabled" end
	local directory = entry.EntryPoint:match("^(games/[%w_/-]+)/[%w_-]+%.lua$")
	if not directory or directory:find("..", 1, true) then return nil, "Invalid game directory" end
	local base = API.GetConfig().BaseUrl .. "/" .. directory .. "/icon."
	if imageCache[base] then return imageCache[base] end
	for _, extension in ipairs(extensions) do
		local content = resolveImage(directory .. "/icon." .. extension, base)
		if content then return content end
	end
	return nil, "No supported icon found"
end
end

-- Copy
do
local translators = {}
function API.Text(value, scope)
	scope = scope or "Shared"
	if not translators[scope] then translators[scope] = makeText(API.TextData, scope) end
	return translators[scope](value)
end

function API.ReloadText()
	local ok, result = pcall(API.LoadModule, "config/Text.lua", nil, true)
	if ok and type(result.Shared) == "table" then
		for _, section in pairs(result) do
			if type(section) ~= "table" then return false, "Text sections must be tables" end
			for key, value in pairs(section) do
				if type(key) ~= "string" or type(value) ~= "string" then return false, "Text entries must have string keys and values" end
			end
		end
		API.TextData = result
		table.clear(translators)
		return true
	end
	return false, ok and "Text.lua must return a Shared table" or result
end
end

-- Utilities
do
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

function API.GetCharacter(player)
	player = player or Players.LocalPlayer
	local character = player and player.Character
	return character,
		character and character:FindFirstChildOfClass("Humanoid"),
		character and character:FindFirstChild("HumanoidRootPart")
end

function API.GetPosition(object)
	if not object then return nil end
	if typeof(object) == "Vector3" then return object end
	if object:IsA("BasePart") then return object.Position end
	if object:IsA("Attachment") then return object.WorldPosition end
	if object:IsA("Model") then
		local ok, pivot = pcall(function() return object:GetPivot() end)
		if ok then return pivot.Position end
	end
	local part = object:FindFirstChildWhichIsA("BasePart", true)
	if part then return part.Position end
	local ancestor = object:FindFirstAncestorWhichIsA("BasePart") or object:FindFirstAncestorWhichIsA("Model")
	if ancestor then return API.GetPosition(ancestor) end
	return nil
end

function API.DistanceToPlayer(target, player)
	local _, _, root = API.GetCharacter(player)
	local position = API.GetPosition(target)
	return root and position and (root.Position - position).Magnitude or math.huge
end

function API.FormatNumber(value, compact)
	value = tonumber(value) or 0
	if value ~= value or math.abs(value) == math.huge then return "—" end
	if compact then
		for _, unit in ipairs({ { 1e15, "Q" }, { 1e12, "T" }, { 1e9, "B" }, { 1e6, "M" }, { 1e3, "K" } }) do
			if math.abs(value) >= unit[1] then
				local number = string.format("%.2f", value / unit[1]):gsub("0+$", ""):gsub("%.$", "")
				return number .. unit[2]
			end
		end
	end
	local sign = value < 0 and "-" or ""
	local digits = tostring(math.floor(math.abs(value) + 0.5))
	return sign .. (compact and digits or digits:reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", ""))
end

function API.FormatDistance(value)
	if not value or value == math.huge then return "far" end
	return tostring(math.floor(value + 0.5)) .. " studs"
end

function API.CreateScope()
	local scope = { Closed = false, _items = {} }
	local function clean(item)
		if type(item) == "function" then item()
		elseif typeof(item) == "RBXScriptConnection" then item:Disconnect()
		elseif type(item.Destroy) == "function" then item:Destroy()
		elseif type(item.Disconnect) == "function" then item:Disconnect() end
	end
	function scope:Track(item)
		if item then
			if self.Closed then pcall(clean, item) else table.insert(self._items, item) end
		end
		return item
	end
	function scope:Destroy()
		if self.Closed then return end
		self.Closed = true
		for index = #self._items, 1, -1 do pcall(clean, self._items[index]) end
		table.clear(self._items)
	end
	return scope
end

-- One scheduler can service an entire suite. Modules register work instead of
-- each owning another RenderStepped or Heartbeat connection.
function API.CreateUpdateManager(options)
	options = options or {}
	local manager = {
		Destroyed = false,
		Jobs = { Render = {}, Heartbeat = {}, Slow = {}, Stats = {} },
		Errors = {},
		_slowElapsed = 0,
		_statsElapsed = 0,
		_connections = {},
	}

	local function run(bucket, deltaTime)
		for name, job in pairs(manager.Jobs[bucket]) do
			local ok, err = pcall(job.Callback, deltaTime)
			if not ok then
				job.Failures += 1
				manager.Errors[name] = tostring(err)
				if options.OnError then pcall(options.OnError, name, err) end
				if job.Failures >= 3 then manager.Jobs[bucket][name] = nil end
			else
				job.Failures = 0
			end
		end
	end

	function manager:Register(name, bucket, callback)
		assert(not self.Destroyed, "Update manager is destroyed")
		assert(type(name) == "string" and name ~= "", "Update job needs a name")
		assert(self.Jobs[bucket], "Unknown update bucket: " .. tostring(bucket))
		assert(type(callback) == "function", "Update callback must be a function")
		for _, jobs in pairs(self.Jobs) do
			assert(jobs[name] == nil, "Duplicate update job: " .. name)
		end
		local job = { Callback = callback, Failures = 0 }
		self.Jobs[bucket][name] = job
		local registration = { Connected = true }
		function registration:Disconnect()
			if not self.Connected then return end
			self.Connected = false
			if manager.Jobs[bucket][name] == job then manager.Jobs[bucket][name] = nil end
		end
		return registration
	end

	function manager:Count()
		local count = 0
		for _, jobs in pairs(self.Jobs) do for _ in pairs(jobs) do count += 1 end end
		return count
	end

	function manager:Destroy()
		if self.Destroyed then return end
		self.Destroyed = true
		for _, connection in ipairs(self._connections) do connection:Disconnect() end
		table.clear(self._connections)
		for _, jobs in pairs(self.Jobs) do table.clear(jobs) end
	end

	table.insert(manager._connections, RunService.RenderStepped:Connect(function(deltaTime)
		if not manager.Destroyed then run("Render", deltaTime) end
	end))
	table.insert(manager._connections, RunService.Heartbeat:Connect(function(deltaTime)
		if manager.Destroyed then return end
		run("Heartbeat", deltaTime)
		manager._slowElapsed += deltaTime
		manager._statsElapsed += deltaTime
		if manager._slowElapsed >= (options.SlowInterval or 0.1) then
			local elapsed = manager._slowElapsed
			manager._slowElapsed = 0
			run("Slow", elapsed)
		end
		if manager._statsElapsed >= (options.StatsInterval or 0.75) then
			local elapsed = manager._statsElapsed
			manager._statsElapsed = 0
			run("Stats", elapsed)
		end
	end))
	return manager
end

function API.CreateCharacterManager(player)
	player = player or Players.LocalPlayer
	local manager = {
		Player = player,
		Character = nil,
		Humanoid = nil,
		Root = nil,
		Destroyed = false,
		_added = {},
		_removing = {},
		_connections = {},
	}

	local function refresh(character)
		manager.Character = character
		manager.Humanoid = character and character:FindFirstChildOfClass("Humanoid") or nil
		manager.Root = character and character:FindFirstChild("HumanoidRootPart") or nil
	end
	local function subscribe(list, callback, immediate)
		assert(type(callback) == "function", "Character callback must be a function")
		local entry = { Callback = callback, Connected = true }
		table.insert(list, entry)
		function entry:Disconnect() self.Connected = false end
		if immediate and manager.Character then
			local character = manager.Character
			task.spawn(function()
				local humanoid = manager.Humanoid or character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 10)
				local root = manager.Root or character:FindFirstChild("HumanoidRootPart") or character:WaitForChild("HumanoidRootPart", 10)
				if entry.Connected and not manager.Destroyed and manager.Character == character then callback(character, humanoid, root) end
			end)
		end
		return entry
	end

	function manager:Get()
		if self.Character ~= self.Player.Character then refresh(self.Player.Character) end
		if self.Character then
			if not self.Humanoid or not self.Humanoid.Parent then self.Humanoid = self.Character:FindFirstChildOfClass("Humanoid") end
			if not self.Root or not self.Root.Parent then self.Root = self.Character:FindFirstChild("HumanoidRootPart") end
		end
		return self.Character, self.Humanoid, self.Root
	end
	function manager:OnAdded(callback, immediate) return subscribe(self._added, callback, immediate ~= false) end
	function manager:OnRemoving(callback) return subscribe(self._removing, callback, false) end
	function manager:Destroy()
		if self.Destroyed then return end
		self.Destroyed = true
		for _, connection in ipairs(self._connections) do connection:Disconnect() end
		table.clear(self._connections)
		table.clear(self._added)
		table.clear(self._removing)
		refresh(nil)
	end

	refresh(player.Character)
	table.insert(manager._connections, player.CharacterAdded:Connect(function(character)
		refresh(character)
		task.spawn(function()
			local humanoid = character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 10)
			local root = character:FindFirstChild("HumanoidRootPart") or character:WaitForChild("HumanoidRootPart", 10)
			if manager.Destroyed or manager.Character ~= character then return end
			manager.Humanoid, manager.Root = humanoid, root
			for _, entry in ipairs(manager._added) do if entry.Connected then task.defer(entry.Callback, character, humanoid, root) end end
		end)
	end))
	table.insert(manager._connections, player.CharacterRemoving:Connect(function(character)
		for _, entry in ipairs(manager._removing) do if entry.Connected then pcall(entry.Callback, character) end end
		refresh(nil)
	end))
	return manager
end
end

-- Feature
do
local Feature = {}
Feature.__index = Feature
API.Feature = Feature

function API.CreateFeature(name, settings)
	return setmetatable({
		Name = name, Settings = settings or {}, Enabled = false, Status = "Ready",
		NextRun = 0, _token = 0, _connections = {}, _stateListeners = {},
	}, Feature)
end

function Feature:_emitState(enabled)
	if self.OnStateChanged then self.OnStateChanged(enabled) end
	for _, listener in ipairs(self._stateListeners) do
		if listener.Connected then pcall(listener.Callback, enabled) end
	end
end

function Feature:ObserveState(callback, immediate)
	assert(type(callback) == "function", "State observer must be a function")
	local listener = { Callback = callback, Connected = true }
	function listener:Disconnect() self.Connected = false end
	table.insert(self._stateListeners, listener)
	if immediate ~= false then callback(self.Enabled) end
	return listener
end

function Feature:AddSetting(key, default)
	if self.Settings[key] == nil then self.Settings[key] = default end
	return self.Settings[key]
end

function Feature:SetSetting(key, value)
	assert(self.Settings[key] ~= nil, "Unknown " .. self.Name .. " setting: " .. tostring(key))
	self.Settings[key] = value
	if self.OnSettingChanged then self:OnSettingChanged(key, value) end
end

function Feature:_syncControl()
	local control = self._control
	if not control then return end
	control:SetEnabled(self.Enabled)
	if control.Toggle then control.Toggle:SetValue(self.Enabled, true) end
	control:SetStatus(self.Status)
end

function Feature:BindControl(control)
	self._control = control
	self:_syncControl()
	return self
end

function Feature:SetStatus(status)
	local value = tostring(status or "")
	if value == self.Status then return end
	self.Status = value
	self:_syncControl()
	if self.OnStatusChanged then self.OnStatusChanged(value) end
end

function Feature:Track(connection)
	if connection then table.insert(self._connections, connection) end
	return connection
end

function Feature:ClearConnections()
	for _, connection in ipairs(self._connections) do pcall(function() connection:Disconnect() end) end
	table.clear(self._connections)
end

function Feature:Enable()
	if self.Enabled then return true end
	self.Enabled = true
	self._token += 1
	local ok, result = pcall(function()
		self:_emitState(true)
		if self.OnEnable then return self:OnEnable(self._token) end
	end)
	if not ok or result == false then
		self:Disable()
		self:SetStatus(ok and "Unable to start" or tostring(result))
		return false
	end
	self:_syncControl()
	return true
end

function Feature:Disable()
	if not self.Enabled then return end
	self.Enabled = false
	self._token += 1
	self:ClearConnections()
	local ok, err = pcall(function()
		if self.OnDisable then self:OnDisable() end
	end)
	local stateOK, stateError = pcall(function()
		self:_emitState(false)
	end)
	if not ok or not stateOK then self.Status = tostring(not ok and err or stateError) end
	self:_syncControl()
end

function Feature:SetEnabled(enabled)
	if enabled then return self:Enable() end
	self:Disable()
	return true
end

function Feature:Destroy()
	self:Disable()
	self:ClearConnections()
	table.clear(self._stateListeners)
	self._control = nil
end
end

-- Universal
do
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local VirtualInputManager
pcall(function() VirtualInputManager = game:GetService("VirtualInputManager") end)

API.UniversalModules = {}

function API.UniversalModules.CreateFlight(options)
	options = options or {}
	local feature = API.CreateFeature(options.Name or "Flight", {
		Speed = options.Speed or 70,
		ToggleKey = options.ToggleKey or Enum.KeyCode.Unknown,
		VerticalSpeed = options.VerticalSpeed or 50,
		Mode = options.Mode or "Character Flight",
		Style = options.Style or "Smooth Flight",
		Direction = options.Direction or "Camera-direction Flight",
		Inertia = options.Inertia or 12,
		FlightHover = options.FlightHover ~= false,
		HoverHeight = options.HoverHeight or 8,
		UpKey = options.UpKey or Enum.KeyCode.Space,
		DownKey = options.DownKey or Enum.KeyCode.LeftControl,
	})
	function feature:_detach(restore)
		if self._velocity then self._velocity:Destroy() end
		if self._orientation then self._orientation:Destroy() end
		if self._attachment then self._attachment:Destroy() end
		if restore and self._humanoid and self._humanoid.Parent and self._controlsCharacter then
			self._humanoid.PlatformStand = self._previousPlatformStand
			self._humanoid.AutoRotate = self._previousAutoRotate
			self._humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
		end
		if restore and self._root and self._root.Parent then self._root.AssemblyLinearVelocity = Vector3.zero end
		self._velocity, self._orientation, self._attachment = nil, nil, nil
		self._humanoid, self._root, self._controlsCharacter = nil, nil, nil
		self._currentVelocity = Vector3.zero
	end

	function feature:_attach(character, humanoid, characterRoot)
		self:_detach(true)
		humanoid = humanoid or (character and character:FindFirstChildOfClass("Humanoid"))
		characterRoot = characterRoot or (character and character:FindFirstChild("HumanoidRootPart"))
		local root = characterRoot
		if self.Settings.Mode == "Vehicle Flight" then
			local seat = humanoid and humanoid.SeatPart
			root = seat and (seat.AssemblyRootPart or seat)
		end
		if not humanoid or not root or humanoid.Health <= 0 then
			self:SetStatus(self.Settings.Mode == "Vehicle Flight" and "Sit in a vehicle to begin" or "Waiting for character")
			return false
		end
		self._humanoid = humanoid
		self._root = root
		self._previousAutoRotate = humanoid.AutoRotate
		self._previousPlatformStand = humanoid.PlatformStand
		self._controlsCharacter = self.Settings.Mode ~= "Vehicle Flight"
		if self._controlsCharacter then
			humanoid.AutoRotate = false
			humanoid.PlatformStand = true
		end
		local attachment = Instance.new("Attachment")
		attachment.Name = "FrostScriptsFlightAttachment"
		attachment.Parent = root
		local velocity = Instance.new("LinearVelocity")
		velocity.Name = "FrostScriptsFlightVelocity"
		velocity.Attachment0 = attachment
		velocity.RelativeTo = Enum.ActuatorRelativeTo.World
		velocity.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
		velocity.ForceLimitsEnabled = false
		velocity.VectorVelocity = Vector3.zero
		velocity.Parent = root
		local orientation = Instance.new("AlignOrientation")
		orientation.Name = "FrostScriptsFlightOrientation"
		orientation.Attachment0 = attachment
		orientation.Mode = Enum.OrientationAlignmentMode.OneAttachment
		orientation.MaxTorque = math.huge
		orientation.Responsiveness = math.max(5, self.Settings.Inertia)
		orientation.Parent = root
		self._attachment = attachment
		self._velocity = velocity
		self._orientation = orientation
		self._mouse = Players.LocalPlayer:GetMouse()
		local raycast = RaycastParams.new()
		raycast.FilterType = Enum.RaycastFilterType.Exclude
		raycast.FilterDescendantsInstances = character and { character } or {}
		self._raycast = raycast
		self._currentVelocity = Vector3.zero
		self:SetStatus(self.Settings.Mode .. " active")
		return true
	end

	function feature:_step(deltaTime)
		local root, humanoid = self._root, self._humanoid
		if not root or not humanoid or not root.Parent or not humanoid.Parent or humanoid.Health <= 0 then
			if root or humanoid then self:_detach(false) end
			if options.CharacterManager then
				local character, nextHumanoid, nextRoot = options.CharacterManager:Get()
				if nextHumanoid and nextRoot and self:_attach(character, nextHumanoid, nextRoot) then return end
			end
			self:SetStatus("Waiting for character")
			return
		end
			local camera = workspace.CurrentCamera
			local look
			if self.Settings.Direction == "Mouse-direction Flight" and self._mouse and self._mouse.Hit then
				look = self._mouse.Hit.Position - root.Position
			elseif self.Settings.Direction == "Character-direction Flight" then
				look = root.CFrame.LookVector
			else
				look = camera and camera.CFrame.LookVector or Vector3.new(0, 0, -1)
			end
			local flatLook = Vector3.new(look.X, 0, look.Z)
			flatLook = flatLook.Magnitude > 0.001 and flatLook.Unit or Vector3.new(0, 0, -1)
			local flatRight = Vector3.new(-flatLook.Z, 0, flatLook.X)
			local move = Vector3.zero
			if UserInputService:GetFocusedTextBox() or (options.IsInputCaptured and options.IsInputCaptured()) then
				self._velocity.VectorVelocity = Vector3.zero
				return
			end
			if UserInputService:IsKeyDown(Enum.KeyCode.W) then move += flatLook end
			if UserInputService:IsKeyDown(Enum.KeyCode.S) then move -= flatLook end
			if UserInputService:IsKeyDown(Enum.KeyCode.D) then move += flatRight end
			if UserInputService:IsKeyDown(Enum.KeyCode.A) then move -= flatRight end
			if options.GetMoveVector then
				local mobile = options.GetMoveVector()
				if typeof(mobile) == "Vector2" then move += flatRight * mobile.X + flatLook * mobile.Y end
			end
			if move.Magnitude > 1 then move = move.Unit end
			local vertical = 0
			if UserInputService:IsKeyDown(self.Settings.UpKey) then vertical += 1 end
			if UserInputService:IsKeyDown(self.Settings.DownKey) then vertical -= 1 end
			if options.GetVertical then vertical += tonumber(options.GetVertical()) or 0 end
			vertical = math.clamp(vertical, -1, 1)
			local mode = self.Settings.Mode
			if mode == "Levitate" and vertical == 0 then vertical = 0.35 end
			if mode == "Hover" and vertical == 0 then
				local hit = workspace:Raycast(root.Position, Vector3.new(0, -500, 0), self._raycast)
				if hit then
					vertical = math.clamp((self.Settings.HoverHeight - hit.Distance) / math.max(1, self.Settings.HoverHeight), -1, 1)
				end
			elseif mode == "Float" and vertical == 0 then
				vertical = 0
			elseif not self.Settings.FlightHover and vertical == 0 then
				vertical = -0.12
			end
			local targetVelocity = move * self.Settings.Speed
				+ Vector3.new(0, vertical * self.Settings.VerticalSpeed, 0)
			if self.Settings.Style == "Instant Flight" then
				self._currentVelocity = targetVelocity
			else
				local response = math.max(1, tonumber(self.Settings.Inertia) or 12)
				self._currentVelocity = self._currentVelocity:Lerp(targetVelocity, 1 - math.exp(-response * deltaTime))
			end
			self._velocity.VectorVelocity = self._currentVelocity
			self._orientation.Responsiveness = math.max(5, tonumber(self.Settings.Inertia) or 12)
			self._orientation.CFrame = CFrame.lookAt(Vector3.zero, flatLook)
	end

	function feature:OnEnable()
		local manager = options.CharacterManager
		local function attach(character, humanoid, root)
			if self.Enabled then self:_attach(character, humanoid, root) end
		end
		if manager then
			self:Track(manager:OnAdded(attach, false))
			self:Track(manager:OnRemoving(function() self:_detach(false) end))
			attach(manager:Get())
		else
			local player = Players.LocalPlayer
			attach(player.Character)
			self:Track(player.CharacterAdded:Connect(function(character) attach(character) end))
		end
		if options.UpdateManager then
			self:Track(options.UpdateManager:Register(self.Name .. ":" .. tostring(self), "Render", function(deltaTime)
				self:_step(deltaTime)
			end))
		else
			self:Track(RunService.RenderStepped:Connect(function(deltaTime) self:_step(deltaTime) end))
		end
		return true
	end
	function feature:OnSettingChanged(key)
		if self.Enabled and (key == "Mode") then
			self:Disable()
			self:Enable()
		elseif self.Enabled then
			self:SetStatus(self.Settings.Mode .. " active")
		end
	end
	function feature:OnDisable()
		self:_detach(true)
		self:SetStatus("Flight disabled")
	end
	return feature
end

function API.UniversalModules.CreateAutoClicker(options)
	options = options or {}
	local feature = API.CreateFeature(options.Name or "Auto Clicker", {
		ClicksPerSecond = options.ClicksPerSecond or 8,
		ToggleKey = options.ToggleKey or Enum.KeyCode.Unknown,
	})
	function feature:Click()
		if not VirtualInputManager then return false, "VirtualInputManager unavailable" end
		if UserInputService:GetFocusedTextBox()
			or UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
			or (options.IsInputCaptured and options.IsInputCaptured()) then return true end
		return pcall(function()
			VirtualInputManager:SendMouseButtonEvent(0, 0, 0, true, game, 0)
			VirtualInputManager:SendMouseButtonEvent(0, 0, 0, false, game, 0)
		end)
	end
	function feature:OnEnable(token)
		if not VirtualInputManager then
			self:SetStatus("VirtualInputManager unavailable")
			return false
		end
		task.spawn(function()
			while self.Enabled and self._token == token do
				local started = os.clock()
				local ok, err = self:Click()
				if not ok then
					self:Disable()
					self:SetStatus(tostring(err))
					break
				end
				local rate = math.clamp(tonumber(self.Settings.ClicksPerSecond) or 8, 1, 30)
				task.wait(math.max(0.02, (1 / rate) - (os.clock() - started)))
			end
		end)
		self:SetStatus("Clicking")
		return true
	end
	function feature:OnDisable()
		self:SetStatus("Stopped")
	end
	return feature
end
end

return API
